// Generated by Cypress Author on 2026-11-10.
// Sign-up, verification, login and session handling, with the API stubbed.
import { buildUser, STUDENT_EMAIL } from "../support/data";

describe("Logging in", () => {
  beforeEach(() => {
    cy.stubApi();
    cy.visit("/login");
  });

  it("wrong password → shows the error and stays on the login page", () => {
    cy.intercept("POST", "/api/auth/login", { statusCode: 401, body: { error: "Invalid email or password" } }).as("login");

    cy.typeFanshaweId("#login-email", "a_student");
    cy.get("#login-password").type("Wrong#2026");
    cy.contains("button", "Log in").click();

    cy.wait("@login").its("request.body").should("deep.equal", { email: STUDENT_EMAIL, password: "Wrong#2026" });
    cy.get('[role="alert"]').should("contain.text", "Invalid email or password");
    cy.location("pathname").should("eq", "/login");
    cy.window().its("localStorage").invoke("getItem", "campushub_token").should("be.null");
  });

  it("correct password → saves the session and leaves the login page", () => {
    const user = buildUser();
    cy.intercept("POST", "/api/auth/login", { body: { token: "fresh-token", user } }).as("login");

    cy.typeFanshaweId("#login-email", "a_student");
    cy.get("#login-password").type("Campus#2026");
    cy.contains("button", "Log in").click();

    cy.wait("@login");
    cy.location("pathname").should("eq", "/");
    cy.window().its("localStorage").invoke("getItem", "campushub_token").should("eq", "fresh-token");
  });

  it("suspended account → explains why with the administrator's reason", () => {
    cy.intercept("POST", "/api/auth/login", {
      statusCode: 403,
      body: { error: "Your account is suspended", code: "ACCOUNT_SUSPENDED", reason: "Spam listings" },
    });

    cy.typeFanshaweId("#login-email", "a_student");
    cy.get("#login-password").type("Campus#2026");
    cy.contains("button", "Log in").click();

    cy.get('[role="alert"]').should("contain.text", "Your account is suspended. Reason: Spam listings.");
  });
});

describe("Signing up", () => {
  beforeEach(() => {
    cy.stubApi();
    cy.visit("/register");
  });

  /** Fills every sign-up field with valid details */
  function fillSignUp(password = "Campus#2026") {
    cy.get("#register-first-name").type("Alex");
    cy.get("#register-last-name").type("Student");
    cy.typeFanshaweId("#register-email", "a_student");
    cy.get("#register-password").type(password);
    cy.get("#register-confirm").type(password);
    cy.get("#register-terms").check();
  }

  it("valid details and the emailed code → account is created and signed in", () => {
    cy.intercept("POST", "/api/auth/register", { statusCode: 201, body: { message: "Check your email for the verification code." } }).as("register");
    cy.intercept("POST", "/api/auth/verify", { body: { token: "new-token", user: buildUser() } }).as("verify");

    fillSignUp();
    cy.contains("button", "Sign up").click();

    cy.wait("@register").its("request.body").should("deep.include", {
      firstName: "Alex", lastName: "Student", email: STUDENT_EMAIL, acceptTerms: true,
    });
    cy.location("pathname").should("eq", "/verify");
    cy.contains(`We sent a 6-digit code to ${STUDENT_EMAIL}`).should("be.visible");

    // Entering the sixth digit submits the code on its own
    "482913".split("").forEach((digit, index) => {
      cy.get(`[aria-label="Digit ${index + 1}"]`).type(digit);
    });

    cy.wait("@verify").its("request.body").should("deep.equal", { email: STUDENT_EMAIL, otp: "482913" });
    cy.location("pathname").should("eq", "/");
    cy.window().its("localStorage").invoke("getItem", "campushub_token").should("eq", "new-token");
  });

  it("email already waiting for verification → shows the server's explanation and stays on the form", () => {
    const message = "A sign-up for this email is already waiting for verification. Enter the code we emailed, or try again in 15 minutes.";
    cy.intercept("POST", "/api/auth/register", { statusCode: 409, body: { error: message } }).as("register");

    fillSignUp("Different#2026");
    cy.contains("button", "Sign up").click();

    cy.wait("@register");
    cy.contains(message).should("be.visible");
    cy.location("pathname").should("eq", "/register");
  });

  it("mismatched passwords → blocks sign-up before calling the API", () => {
    cy.intercept("POST", "/api/auth/register", cy.spy().as("registerCall"));

    cy.get("#register-first-name").type("Alex");
    cy.get("#register-last-name").type("Student");
    cy.typeFanshaweId("#register-email", "a_student");
    cy.get("#register-password").type("Campus#2026");
    cy.get("#register-confirm").type("Campus#2027");
    cy.get("#register-terms").check();
    cy.contains("button", "Sign up").click();

    cy.contains("Passwords do not match").should("be.visible");
    cy.get("@registerCall").should("not.have.been.called");
  });
});

describe("Sessions", () => {
  beforeEach(() => {
    cy.stubApi();
  });

  it("opening a members-only page while signed out → redirects to login", () => {
    cy.visit("/messages");
    cy.location("pathname").should("eq", "/login");
  });

  it("session ended on the server (e.g. password reset elsewhere) → signs out and asks to log in again", () => {
    // After a password reset, the API answers every older token with 401
    cy.intercept("GET", "/api/conversations*", { statusCode: 401, body: { error: "Account is not active" } }).as("conversations");

    cy.visitSignedIn("/messages");

    cy.wait("@conversations");
    cy.location("pathname").should("eq", "/login");
    cy.location("search").should("eq", "?expired=true");
    cy.contains("Please log in again").should("be.visible");
    cy.window().its("localStorage").invoke("getItem", "campushub_token").should("be.null");
  });
});
